if we measure from the other side\n\n# Let me recalculate more carefully\n# P(0) = e^(-yT)\n# P(1) = e^(-y(T-1))\n# P(1)/P(0) = e^y\n# y = ln(P(1)/P(0))\n\n# D = - (1/P) * dP/dy = T (for zero coupon)\n# T = -ln(P(0))/y\n\nprint(f\"\\nAlternative calculation: D = -ln(P_1953)/ln(P_1954/P_1953) = {-math.log(P_1953)/math.log(P_1954/P_1953)}\")\nEOF"}}},"_meta":{"goose_extension":"developer"}}],"metadata":{"userVisible":true,"agentVisible":true}}}
